import { mapLimit } from '../src/map-limit.mjs';
test('maps ordinary values',async()=>{assert.deepEqual(await mapLimit([1,2],2,x=>x*2),[{status:'fulfilled',value:2},{status:'fulfilled',value:4}]);});
